using System;
using System.Collections.Generic;
using Epic.OnlineServices;
using Epic.OnlineServices.Lobby;
using Idas3.Multiplayer;
static class EosActivityDriver {
    static int checks;
    static void Check(bool value,string name){if(!value)throw new Exception(name);++checks;Console.WriteLine("PASS\t"+name);}
    static Idas3EosActivity.Entry Entry(string owner,string state,long at)=>new Idas3EosActivity.Entry{Owner=owner,State=state,At=at};
    static Idas3EosActivity Module(LobbyInterface lobby,Idas3EosTransport owner=null)=>new Idas3EosActivity(owner??new Idas3EosTransport(),lobby,new ProductUserId("local"),()=>12.5);
    static LobbyDetails Room(string owner,string state,long at){var room=new LobbyDetails{Info=new LobbyDetailsInfo{BucketId=Idas3EosActivity.Bucket,LobbyOwnerUserId=new ProductUserId(owner),MaxMembers=1,AvailableSlots=0,PermissionLevel=LobbyPermissionLevel.Publicadvertised}};room.Values[Idas3EosActivity.SchemaKey]=new AttributeDataValue{AsInt64=1};room.Values[Idas3EosActivity.StateKey]=new AttributeDataValue{AsUtf8=state};room.Values[Idas3EosActivity.TimeKey]=new AttributeDataValue{AsInt64=at};return room;}
    static void Summary(){
        var rows=new[]{Entry("a","online",1000),Entry("b","queuing",1000),Entry("c","racing",1000)};var result=Idas3EosActivity.Summarize(rows,3,1000,12.5);
        Check(result.Available&&result.Online==3&&result.Queuing==1&&result.Racing==1&&!result.Limited&&result.ObservedAt==12.5,"State counts and caller's monotonic clock");
        result=Idas3EosActivity.Summarize(new[]{Entry("a","racing",990),Entry("a","online",1000),Entry("a","queuing",980)},3,1000,0);Check(result.Online==1&&result.Queuing==0&&result.Racing==0,"Newest authenticated owner entry wins and duplicates cannot inflate count");
        result=Idas3EosActivity.Summarize(new[]{Entry("expired","online",909),Entry("boundary","online",910),Entry("future","online",1031),Entry("near","online",1030),Entry("bad","unknown",1000),Entry(null,"online",1000)},6,1000,0);Check(result.Online==2,"Expiry, future clock bound, malformed owner and invalid state");
        var many=new List<Idas3EosActivity.Entry>();for(int i=0;i<201;i++)many.Add(Entry(i.ToString(),"online",1000));result=Idas3EosActivity.Summarize(many,201,1000,0);Check(result.Online==200&&result.Limited,"Census caps at200 with lower-bound marker");
        result=Idas3EosActivity.Summarize(rows,200,1000,0);Check(result.Online==3&&result.Limited,"Saturated raw search stays limited after dedup/filtering");
        result=Idas3EosActivity.Summarize(new Idas3EosActivity.Entry[0],0,1000,0);Check(result.Available&&result.Online==0&&!result.Limited,"Successful empty survey is zero");
    }
    static void Publish(){var lobby=new LobbyInterface();var owner=new Idas3EosTransport{IsBusy=true};var module=Module(lobby,owner);module.Poll(false,false,"online");Check(lobby.Creates.Count==0&&lobby.Searches==0,"Disabled diagnostics do not publish or survey");module.Poll(true,false,"online");Check(lobby.Creates.Count==1&&lobby.Creates[0].MaxLobbyMembers==1&&!lobby.Creates[0].EnableJoinById&&!lobby.Creates[0].EnableRTCRoom&&!lobby.Creates[0].PresenceEnabled,"Busy queue publishes full non-joinable activity lobby");lobby.CompleteCreate();Check(lobby.Updates==1&&lobby.LastEdit.Values.Count==3&&!lobby.LastEdit.Values.ContainsKey("name"),"Heartbeat publishes only schema state and time");Idas3EosPlatform.Now+=31;module.Poll(true,false,"online");Check(lobby.Updates==2&&lobby.Searches>=2,"Background refresh continues while busy without open menu");module.Poll(true,false,"queuing");Check(lobby.Updates==2,"State changes are coalesced");Idas3EosPlatform.Now+=5;module.Poll(true,false,"queuing");Check(lobby.Updates==3&&lobby.LastEdit.Values[Idas3EosActivity.StateKey].AsUtf8=="queuing","Queued state publishes within five seconds");module.Dispose();Check(lobby.Destroys.Count==1,"Publisher destruction requests cloud cleanup");lobby.CompleteDestroy();}
    static void Survey(){var lobby=new LobbyInterface();long now=DateTimeOffset.UtcNow.ToUnixTimeSeconds();lobby.Results.Add(Room("good","racing",now));var wrong=Room("wrong","online",now);wrong.Info.BucketId="race-room";lobby.Results.Add(wrong);var capacity=Room("capacity","online",now);capacity.Info.MaxMembers=2;lobby.Results.Add(capacity);var stale=Room("stale","online",now-91);lobby.Results.Add(stale);var forged=Room("good","online",now-1);forged.Values["owner"]=new AttributeDataValue{AsUtf8="forged"};lobby.Results.Add(forged);var module=Module(lobby);module.Poll(false,true,"online");Check(module.Snapshot.Online==1&&module.Snapshot.Racing==1,"Search validates bucket shape stale data and true owner");Check(lobby.Parameters.Count==2&&lobby.Parameters[1].Parameter.Value.AsInt64==0,"Full presence lobbies explicitly included");lobby.FindResult=Result.ServiceFailure;Idas3EosPlatform.Now+=31;module.Poll(false,true,"online");Check(module.Snapshot.Available&&module.Snapshot.Online==1,"Temporary survey failure preserves fresh successful sample");Idas3EosPlatform.Now+=15;Check(!module.Snapshot.Available,"Failed survey expires to unavailable, not zero");module.Dispose();}
    static void LateCreate(){var lobby=new LobbyInterface();var module=Module(lobby);module.Poll(true,false,"online");module.Dispose();var next=Module(lobby);next.Poll(true,false,"online");Check(lobby.Creates.Count==1,"New publisher waits for prior retirement");lobby.CompleteCreate();Check(lobby.Destroys.Count==1&&lobby.Updates==0,"Late-created retired lobby is destroyed without advertising");lobby.CompleteDestroy();Check(lobby.Creates.Count==2,"Cleanup completion permits next publisher");lobby.CompleteCreate();next.Dispose();lobby.CompleteDestroy();}
    static void LateQuery(){var lobby=new LobbyInterface{HoldFind=true};var module=Module(lobby);module.Poll(false,true,"online");var search=lobby.LastSearch;module.Dispose();Check(search.Releases==0,"Pending search handle retained until callback");lobby.CompleteFind();Check(search.Releases==1&&!module.Snapshot.Available,"Late query releases handle without reviving disposed snapshot");}
    static void LateUpdate(){var lobby=new LobbyInterface{HoldUpdate=true};var module=Module(lobby);module.Poll(true,false,"online");lobby.CompleteCreate();var edit=lobby.LastEdit;module.Dispose();Check(edit.Releases==0&&lobby.Destroys.Count==0,"Pending update retains handle before retirement");lobby.CompleteUpdate();Check(edit.Releases==1&&lobby.Destroys.Count==1,"Late update releases handle then removes presence");lobby.CompleteDestroy();}
    static void Pacing(){var lobby=new LobbyInterface();var module=Module(lobby);Idas3EosTransport.PaceAvailable=false;module.Poll(true,false,"online");Check(lobby.Creates.Count==0,"Publisher does not reserve a busy future mutation slot");Idas3EosTransport.PaceAvailable=true;Idas3EosPlatform.Now+=.3;module.Poll(true,false,"online");lobby.CompleteCreate();Check(lobby.Updates==1,"Publisher retries a free mutation slot");module.Dispose();lobby.CompleteDestroy();}
    static int Main(string[] args){try{switch(args[0]){case "summary":Summary();break;case "publish":Publish();break;case "survey":Survey();break;case "late-create":LateCreate();break;case "late-query":LateQuery();break;case "late-update":LateUpdate();break;case "pacing":Pacing();break;default:throw new Exception("unknown");}return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
